effects.frag:
if (u_pass == 0) {
  vec4 c = texture(u_tex, v_st);
  float brightness = luma(c.rgb / max(c.a, .001));
  float gate = smoothstep(u_threshold / 100. - .08, u_threshold / 100. + .08, brightness);
  o = c * gate;
  return;
}

vec2 direction = u_pass == 1 ? vec2(1., 0.) : vec2(0., 1.);
float radius = max(u_radius, .5);
float sigma = radius * .5;
vec4 bloom = vec4(0.);
float weightSum = 0.;
for (int i = -20; i <= 20; i++) {
  float x = float(i) / 20. * radius;
  float weight = exp(-(x * x) / (2. * sigma * sigma + 1e-4));
  bloom += texture(u_tex, v_st + direction * u_texel * x) * weight;
  weightSum += weight;
}
bloom /= max(weightSum, 1e-4);

if (u_pass == 2) {
  float angle = radians(u_gradientAngle);
  vec2 axis = vec2(cos(angle), sin(angle));
  float shifted = dot(v_st - .5, axis) + .5 + u_gradientOffset / 100.;
  float repeatPhase = shifted * 100. / max(u_gradientRepeatSize, 1.);
  float gradient = u_gradientRepeat > .5
    ? 1. - abs(mod(repeatPhase, 2.) - 1.)
    : clamp(shifted, 0., 1.);

  vec3 colors[8];
  colors[0] = u_gradientStart;
  colors[1] = u_gradientMiddle;
  colors[2] = u_gradientEnd;
  colors[3] = u_gradientPoint4;
  colors[4] = u_gradientPoint5;
  colors[5] = u_gradientPoint6;
  colors[6] = u_gradientPoint7;
  colors[7] = u_gradientPoint8;
  float positions[8];
  positions[0] = u_gradientPoint1Position / 100.;
  positions[1] = u_gradientMiddlePosition / 100.;
  positions[2] = u_gradientPoint3Position / 100.;
  positions[3] = u_gradientPoint4Position / 100.;
  positions[4] = u_gradientPoint5Position / 100.;
  positions[5] = u_gradientPoint6Position / 100.;
  positions[6] = u_gradientPoint7Position / 100.;
  positions[7] = u_gradientPoint8Position / 100.;
  int pointCount = int(clamp(floor(u_gradientPointCount + .5), 2., 8.));
  for (int pass = 0; pass < 7; pass++) {
    for (int i = 0; i < 7; i++) {
      if (i >= pointCount - 1) continue;
      if (positions[i] > positions[i + 1]) {
        float oldPosition = positions[i];
        positions[i] = positions[i + 1];
        positions[i + 1] = oldPosition;
        vec3 oldColor = colors[i];
        colors[i] = colors[i + 1];
        colors[i + 1] = oldColor;
      }
    }
  }
  vec3 tint = colors[0];
  for (int i = 0; i < 7; i++) {
    if (i >= pointCount - 1) break;
    float start = positions[i];
    float end = max(positions[i + 1], start + .0001);
    if (gradient >= start) tint = mix(colors[i], colors[i + 1], clamp((gradient - start) / (end - start), 0., 1.));
  }
  float pulse = 1. - (u_pulseAmount / 100.) * .5
              + (u_pulseAmount / 100.) * .5 * sin(6.2831853 * u_time * u_pulseSpeed);
  float strength = (u_intensity / 100.) * max(pulse, 0.);
  vec4 original = texture(u_orig, v_st);
  vec4 coloredGlow = vec4(bloom.rgb * tint, bloom.a) * strength;
  o = u_behindLayer > .5
    ? original + coloredGlow * (1. - original.a)
    : original + coloredGlow;
} else {
  o = bloom;
}
